import React, { useEffect, useState } from 'react';

function App() {
  const [logs, setLogs] = useState([]);

  useEffect(() => {
    const eventSource = new EventSource('http://localhost:5001/stream');

    eventSource.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        console.log('Received SSE data:', data);
        if (Array.isArray(data)) {
          setLogs(data);
        } else {
          console.warn('SSE data is not an array:', data);
        }
      } catch (error) {
        console.error('Error parsing SSE data:', error);
      }
    };

    eventSource.onerror = (error) => {
      console.error('SSE error:', error);
      eventSource.close();
    };

    return () => {
      eventSource.close();
    };
  }, []);

  // Debug: log current logs state
  console.log('Current logs:', logs);

  // Download logs as JSON file
  const downloadLogs = () => {
    const element = document.createElement('a');
    const file = new Blob([JSON.stringify(logs, null, 2)], { type: 'application/json' });
    element.href = URL.createObjectURL(file);
    element.download = 'threat_logs.json';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h2>Threat Log</h2>
      <div style={{ border: '1px solid #ccc', padding: '10px', height: '400px', overflowY: 'scroll', backgroundColor: '#f9f9f9' }}>
        {logs.length === 0 ? (
          <p>No logs available</p>
        ) : (
          logs.map(log => (
            <div key={log.id} style={{ marginBottom: '15px', paddingBottom: '10px', borderBottom: '1px solid #ddd' }}>
              <div><strong>Time:</strong> {log.timestamp}</div>
              <div><strong>Threat:</strong> {log.threat_name}</div>
              <div><strong>Location:</strong> {log.threat_location || log.website || 'N/A'}</div>
              <div><strong>Message:</strong> {log.message}</div>
              <div><strong>Solution:</strong> {log.solution}</div>
              {log.engine_name && <div><strong>Engine Name:</strong> {log.engine_name}</div>}
              {log.category && <div><strong>Category:</strong> {log.category}</div>}
              {log.method && <div><strong>Method:</strong> {log.method}</div>}
              {log.engine_update && <div><strong>Engine Update:</strong> {log.engine_update}</div>}
              {log.engine_version && <div><strong>Engine Version:</strong> {log.engine_version}</div>}
              {log.threat_type && <div><strong>Threat Type:</strong> {log.threat_type}</div>}
              {log.platform_type && <div><strong>Platform Type:</strong> {log.platform_type}</div>}
              {log.threat_entry_type && <div><strong>Threat Entry Type:</strong> {log.threat_entry_type}</div>}
              {log.cache_duration && <div><strong>Cache Duration:</strong> {log.cache_duration}</div>}
              <div><strong>URLhaus ID:</strong> {log.urlhaus_id || 'N/A'}</div>
              <div><strong>URLhaus URL:</strong> {log.urlhaus_url || 'N/A'}</div>
              <div><strong>Date Added:</strong> {log.urlhaus_dateadded || 'N/A'}</div>
              <div><strong>Last Seen:</strong> {log.urlhaus_lastseen || 'N/A'}</div>
              <div><strong>Reporter:</strong> {log.urlhaus_reporter || 'N/A'}</div>
              <div><strong>Tags:</strong> {(log.urlhaus_tags && log.urlhaus_tags.length > 0) ? log.urlhaus_tags.join(', ') : 'N/A'}</div>
              <div><strong>Payload:</strong> {log.urlhaus_payload || 'N/A'}</div>
              <div><strong>Payload Type:</strong> {log.urlhaus_payload_type || 'N/A'}</div>
              <div><strong>Traffic:</strong> {log.urlhaus_traffic || 'N/A'}</div>
              <div><strong>SSL:</strong> {log.urlhaus_ssl || 'N/A'}</div>
              <div><strong>Referer:</strong> {log.urlhaus_referer || 'N/A'}</div>
              <div><strong>Country:</strong> {log.urlhaus_country || 'N/A'}</div>
              <div><strong>ASN:</strong> {log.urlhaus_asn || 'N/A'}</div>
              <div><strong>ASN Name:</strong> {log.urlhaus_asnname || 'N/A'}</div>
              <div>
                <strong>Full Threat Data:</strong>
                <pre style={{ whiteSpace: 'pre-wrap', wordWrap: 'break-word', maxHeight: '150px', overflowY: 'auto', backgroundColor: '#eee', padding: '10px', borderRadius: '4px' }}>
                  {log.urlhaus_full_data || 'N/A'}
                </pre>
              </div>
              <div>
                <strong>Full Data:</strong>
                <pre style={{ whiteSpace: 'pre-wrap', wordWrap: 'break-word', maxHeight: '150px', overflowY: 'auto', backgroundColor: '#eee', padding: '10px', borderRadius: '4px' }}>
                  {log.full_data || 'N/A'}
                </pre>
              </div>
            </div>
          ))
        )}
      </div>
      <button onClick={downloadLogs} style={{ marginTop: '10px', padding: '8px 16px', cursor: 'pointer' }}>
        Download Logs
      </button>
    </div>
  );
}

export default App;
